"""Generated by antenna_agent. Requires ANSYS Electronics Desktop + pyaedt (ansys-aedt-core)."""
import csv, os, sys
from pathlib import Path

# HFSS Student 2025 R2: le transport gRPC par defaut (WNUA) echoue -> forcer l'ancien mode
# (PyAEDT issue #7842 + Troubleshooting). Doit etre fait avant tout lancement.
if os.environ.get("AEDT_STUDENT", "0") == "1":
    os.environ.setdefault("PYAEDT_USE_PRE_GRPC_ARGS", "True")

try:
    from ansys.aedt.core import Hfss          # pyaedt >= 0.9
except ImportError:
    from pyaedt import Hfss                    # older releases

OUT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
OUT.mkdir(parents=True, exist_ok=True)
VERSION = os.environ.get("AEDT_VERSION") or None        # e.g. "2025.1"
NON_GRAPHICAL = os.environ.get("AEDT_GUI", "0") != "1"

try:  # HFSS Student can take minutes to start: give PyAEDT a long launch timeout (seconds, env AEDT_TIMEOUT)
    from ansys.aedt.core.generic.settings import settings as _pyaedt_settings
    if os.environ.get('AEDT_SECURE','0')!='1':
        _pyaedt_settings.grpc_secure_mode = False  # WNUA echoue avec HFSS Student
    _pyaedt_settings.desktop_launch_timeout = int(os.environ.get("AEDT_TIMEOUT", "300"))
    if os.environ.get("AEDT_COM", "0") == "1":   # mode COM (sans gRPC): lance ansysedtsv.exe sans argument
        _pyaedt_settings.use_grpc_api = False
except Exception:
    pass


def open_hfss():
    kw = dict(project=str(OUT / "antenna.aedt"), design="antenna", solution_type="Modal",
              version=VERSION, non_graphical=NON_GRAPHICAL,
              student_version=os.environ.get("AEDT_STUDENT", "0") == "1")
    port = os.environ.get("AEDT_PORT")                     # attach to an AEDT started by hand with -grpcsrv <port>
    if port:
        kw["port"] = int(port)
    for flag in ("new_desktop", "new_desktop_session"):    # kwarg was renamed between releases
        try:
            return Hfss(**kw, **{flag: not port})
        except TypeError:
            continue
    raise RuntimeError("unsupported pyaedt Hfss() signature")


hfss = open_hfss()
try:
    hfss.modeler.model_units = "mm"

    mat = hfss.materials.add_material("sub_FR4")
    mat.permittivity = 4.4
    mat.dielectric_loss_tangent = 0.02
    hfss.modeler.create_box([-1.529487, 0.000000, 1.600000], [3.058975, 38.290000, 0.035000], name="ms", material="pec")
    hfss.modeler.create_box([-1.529487, 33.270000, 1.600000], [32.289487, 5.020000, 0.035000], name="t_bar1", material="pec")
    hfss.modeler.create_box([0.000000, 46.450000, 1.600000], [30.760000, 5.020000, 0.035000], name="t_bar2", material="pec")
    hfss.modeler.create_box([0.000000, 59.630000, 1.600000], [28.299200, 5.020000, 0.035000], name="t_bar3", material="pec")
    hfss.modeler.create_box([0.000000, 72.810000, 1.600000], [28.299200, 5.020000, 0.035000], name="t_bar4", material="pec")
    hfss.modeler.create_box([0.000000, 85.990000, 1.600000], [26.035264, 5.020000, 0.035000], name="t_bar5", material="pec")
    hfss.modeler.create_box([0.000000, 99.170000, 1.600000], [26.035264, 5.020000, 0.035000], name="t_bar6", material="pec")
    hfss.modeler.create_box([0.000000, 112.350000, 1.600000], [23.952443, 5.020000, 0.035000], name="t_bar7", material="pec")
    hfss.modeler.create_box([18.932443, 114.560000, 1.600000], [5.020000, 11.000000, 0.035000], name="t_tail", material="pec")
    hfss.modeler.create_box([23.230000, 33.270000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con1", material="pec")
    hfss.modeler.create_box([0.000000, 46.450000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con2", material="pec")
    hfss.modeler.create_box([20.769200, 59.630000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con3", material="pec")
    hfss.modeler.create_box([0.000000, 72.810000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con4", material="pec")
    hfss.modeler.create_box([18.505264, 85.990000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con5", material="pec")
    hfss.modeler.create_box([0.000000, 99.170000, 1.600000], [7.530000, 18.200000, 0.035000], name="t_con6", material="pec")
    hfss.modeler.create_box([-10.419487, 2.510000, 1.600000], [20.838975, 3.058975, 0.035000], name="stub", material="pec")
    hfss.modeler.create_box([-34.530000, 0.000000, -0.035000], [69.060000, 16.950000, 0.035000], name="gnd", material="pec")
    hfss.modeler.create_box([-1.529487, 16.450000, -0.035000], [3.058975, 21.840000, 0.035000], name="bstrip", material="pec")
    hfss.modeler.create_box([-30.760000, 33.270000, -0.035000], [32.289487, 5.020000, 0.035000], name="b_bar1", material="pec")
    hfss.modeler.create_box([-30.760000, 46.450000, -0.035000], [30.760000, 5.020000, 0.035000], name="b_bar2", material="pec")
    hfss.modeler.create_box([-28.299200, 59.630000, -0.035000], [28.299200, 5.020000, 0.035000], name="b_bar3", material="pec")
    hfss.modeler.create_box([-28.299200, 72.810000, -0.035000], [28.299200, 5.020000, 0.035000], name="b_bar4", material="pec")
    hfss.modeler.create_box([-26.035264, 85.990000, -0.035000], [26.035264, 5.020000, 0.035000], name="b_bar5", material="pec")
    hfss.modeler.create_box([-26.035264, 99.170000, -0.035000], [26.035264, 5.020000, 0.035000], name="b_bar6", material="pec")
    hfss.modeler.create_box([-23.952443, 112.350000, -0.035000], [23.952443, 5.020000, 0.035000], name="b_bar7", material="pec")
    hfss.modeler.create_box([-23.952443, 114.560000, -0.035000], [5.020000, 11.000000, 0.035000], name="b_tail", material="pec")
    hfss.modeler.create_box([-30.760000, 33.270000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con1", material="pec")
    hfss.modeler.create_box([-7.530000, 46.450000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con2", material="pec")
    hfss.modeler.create_box([-28.299200, 59.630000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con3", material="pec")
    hfss.modeler.create_box([-7.530000, 72.810000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con4", material="pec")
    hfss.modeler.create_box([-26.035264, 85.990000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con5", material="pec")
    hfss.modeler.create_box([-7.530000, 99.170000, -0.035000], [7.530000, 18.200000, 0.035000], name="b_con6", material="pec")
    hfss.modeler.create_box([-34.530000, 0.000000, 0.000000], [69.060000, 125.560000, 1.600000], name="substrate", material="sub_FR4")
    hfss.modeler.unite(['ms', 't_bar1', 't_bar2', 't_bar3', 't_bar4', 't_bar5', 't_bar6', 't_bar7', 't_tail', 't_con1', 't_con2', 't_con3', 't_con4', 't_con5', 't_con6', 'stub'])
    hfss.modeler.unite(['gnd', 'b_bar1', 'b_bar2', 'b_bar3', 'b_bar4', 'b_bar5', 'b_bar6', 'b_bar7', 'b_tail', 'b_con1', 'b_con2', 'b_con3', 'b_con4', 'b_con5', 'b_con6', 'bstrip'])
    hfss.modeler.create_rectangle("ZX", [-4.800000, 0.000000, 0.000000], [1.600000, 9.600000], name="port_sheet")
    _ax = getattr(hfss, 'axis_directions', None) or getattr(hfss, 'AxisDir', None)
    if _ax is None:
        from ansys.aedt.core.generic.constants import Gravity as _ax
    try:
        hfss.lumped_port(assignment="port_sheet", integration_line=_ax.ZPos, impedance=50.0, name="P1", renormalize=True)
    except TypeError:                                  # pyaedt < 0.9
        hfss.create_lumped_port_to_sheet("port_sheet", axisdir=_ax.ZPos, impedance=50.0, portname="P1", renorm=True)
    # ---- open region (lambda/4 at the lowest frequency) + radiation boundary
    if hasattr(hfss.modeler, 'create_air_region'):
        region = hfss.modeler.create_air_region(49.9654, 49.9654, 49.9654, 49.9654, 49.9654, 49.9654, is_percentage=False)
    else:
        region = hfss.modeler.create_region([49.9654] * 6, 'Absolute Offset')
    hfss.assign_radiation_boundary_to_objects(region.name)
    # ---- setup + interpolating sweep
    setup = hfss.create_setup("Setup1")
    setup.props["Frequency"] = "1.795000GHz"
    setup.props["MaxDeltaS"] = 0.02
    setup.props["MaximumPasses"] = 20
    setup.update()
    sweep = hfss.create_linear_count_sweep("Setup1", "GHz", 1.500000, 2.100000, 201, sweep_type="Interpolating")
    fsweep = hfss.create_linear_count_sweep("Setup1", "GHz", 1.71, 1.88, 3, sweep_type="Discrete", save_fields=True)
    FIELDS = [1.71, 1.795, 1.88]
    hfss.analyze_setup("Setup1")

    # ---- results (API robuste: pyaedt >= 1.x utilise get_expression_data, avant data_real/data_imag)
    def _col(sd, expr, kind):
        if hasattr(sd, "get_expression_data"):
            return list(sd.get_expression_data(expression=expr, formula=kind)[1])
        return list(sd.data_real(expr) if kind == "real" else sd.data_imag(expr))

    setup_sweep = f"Setup1 : {sweep.name}"
    sol = hfss.post.get_solution_data(expressions=["S(1,1)"], setup_sweep_name=setup_sweep)
    unit = (getattr(sol, "units_sweeps", {}) or {}).get("Freq") or "GHz"
    scale = {"Hz": 1e-9, "kHz": 1e-6, "MHz": 1e-3, "GHz": 1.0}[unit]
    f = [x * scale for x in sol.primary_sweep_values]
    re_, im_ = _col(sol, "S(1,1)", "real"), _col(sol, "S(1,1)", "imag")
    with open(OUT / "s11.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["f_GHz", "re", "im"])
        w.writerows(zip(f, re_, im_))


    # ---- far field (best effort: S11 above is already saved)
    try:
        make_sphere = getattr(hfss, "insert_infinite_sphere", None) or hfss.create_infinite_sphere
        make_sphere(phi_start=0, phi_stop=360, phi_step=2, theta_start=0, theta_stop=180, theta_step=2,
                    units="deg", name="Inf")
        rows = []
        pat_rows = []
        for fr in FIELDS:
            sd = hfss.post.get_far_field_data(expressions="dB(GainTotal)", setup_sweep_name=f"Setup1 : {fsweep.name}",
                                              domain="Inf", sweeps={"Freq": [f"{fr}GHz"], "Theta": ["All"], "Phi": ["All"]})
            # get_expression_data ne renvoie qu'une tranche (Phi fixe) -> lire le tableau complet (toutes directions)
            try:
                import numpy as _np
                arr = _np.asarray(sd._solutions_real["dB(GainTotal)"], dtype=float)
                names = list(sd._sweeps_names)
                i = int(arr[:, -1].argmax())
                row = {n: arr[i, k] for k, n in enumerate(names)}
                rows.append((fr, float(arr[i, -1]), row.get("Theta", float("nan")), row.get("Phi", float("nan"))))
                # diagramme complet (toutes directions) pour tracer les coupes de rayonnement
                it, ip = names.index("Theta"), names.index("Phi")
                pat_rows.extend((fr, float(r[it]), float(r[ip]), float(r[-1])) for r in arr)
            except Exception:
                rows.append((fr, max(_col(sd, "dB(GainTotal)", "real")), float("nan"), float("nan")))
        if pat_rows:
            with open(OUT / "patterns.csv", "w", newline="") as fh:
                w = csv.writer(fh)
                w.writerow(["f_GHz", "theta_deg", "phi_deg", "gain_dBi"])
                w.writerows(pat_rows)
        with open(OUT / "gain.csv", "w", newline="") as fh:
            w = csv.writer(fh)
            w.writerow(["f_GHz", "peak_gain_dBi", "theta_deg", "phi_deg"])
            w.writerows(rows)
    except Exception as e:  # inspect fields manually in AEDT: Results > Create Far Fields Report
        (OUT / "gain_error.txt").write_text(repr(e))


    # ---- reports INSIDE HFSS (Results tree): S11, VSWR, Zin, gain, radiation patterns; images exported to OUT
    _log = []

    def _rep(name, expressions, sweep_name, **kw):
        try:
            r = hfss.post.create_report(expressions=expressions, setup_sweep_name=sweep_name, plot_name=name, **kw)
            if not r:
                raise RuntimeError("create_report returned False")
            try:
                hfss.post.export_report_to_jpg(str(OUT), name)
            except Exception as ee:
                _log.append(f"{name}: created, image export failed: {ee!r}")
                return True
            _log.append(f"{name}: OK")
            return True
        except Exception as ee:
            _log.append(f"{name}: FAILED {ee!r}")
            return False

    _rep("S11_dB", ["dB(S(1,1))"], setup_sweep)
    if not _rep("VSWR", ["VSWR(1)"], setup_sweep):
        _rep("VSWR", ["(1+mag(S(1,1)))/(1-mag(S(1,1)))"], setup_sweep)
    _rep("Zin_R_X", ["re(Z(1,1))", "im(Z(1,1))"], setup_sweep)
    _rep("Smith_S11", ["S(1,1)"], setup_sweep, plot_type="Smith Chart")


    if (OUT / "gain.csv").exists():
        _fs = f"Setup1 : {fsweep.name}"
        _ff = dict(report_category="Far Fields", context="Inf")
        _rep("Gain_vs_freq", ["dB(GainTotal)"], _fs, variations={"Freq": ["All"], "Theta": ["90deg"], "Phi": ["90deg"]},
             primary_sweep_variable="Freq", **_ff)
        for _fr in FIELDS:
            _rep(f"Pattern_YZ_{_fr}GHz", ["dB(GainTotal)"], _fs,
                 variations={"Freq": [f"{_fr}GHz"], "Theta": ["All"], "Phi": ["90deg"]},
                 primary_sweep_variable="Theta", plot_type="Radiation Pattern", **_ff)
            _rep(f"Pattern_XY_{_fr}GHz", ["dB(GainTotal)"], _fs,
                 variations={"Freq": [f"{_fr}GHz"], "Theta": ["90deg"], "Phi": ["All"]},
                 primary_sweep_variable="Phi", plot_type="Radiation Pattern", **_ff)
        _fc = FIELDS[len(FIELDS) // 2]
        _rep(f"Gain3D_{_fc}GHz", ["dB(GainTotal)"], _fs,
             variations={"Freq": [f"{_fc}GHz"], "Theta": ["All"], "Phi": ["All"]},
             primary_sweep_variable="Phi", secondary_sweep_variable="Theta", plot_type="3D Polar Plot", **_ff)


    (OUT / "reports_log.txt").write_text("\n".join(_log))


    hfss.save_project()
finally:
    try:
        hfss.release_desktop(close_projects=True, close_desktop=True)
    except Exception:
        pass
